package com.example.appanh;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import androidx.core.content.FileProvider;
import com.example.appanh.models.Photo;
import java.io.File;
public class ShareActivity extends BaseActivity {
 private Photo photo;
 @Override public void onCreate(Bundle state){super.onCreate(state);screen(R.layout.sheet_share);repo.load((p,a,error)->{photo=repo.find(getIntent().getStringExtra("photoId"));result(error);});click(R.id.cancel,this::finish);click(R.id.shareFile,()->{if(photo!=null)openFile(this,repo,photo,true);});click(R.id.shareLink,()->{if(photo==null)return;if(photo.getFirebaseUrl()==null||photo.getFirebaseUrl().isEmpty()){toast("Ảnh này chưa có liên kết cloud. Hãy chọn Chia sẻ tệp; sao lưu hiện chỉ là giao diện minh họa.");return;}new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Chia sẻ liên kết?").setMessage("Bất kỳ ai có liên kết đều có thể tải ảnh này.").setNegativeButton("Hủy",null).setPositiveButton("Chia sẻ",(d,w)->startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,photo.getFirebaseUrl()),"Chia sẻ liên kết"))).show();});}
 public static void openFile(android.app.Activity context,GalleryRepository repo,Photo photo,boolean share){Object source=repo.source(photo);if(source==null){android.widget.Toast.makeText(context,"Không tìm thấy file.",android.widget.Toast.LENGTH_LONG).show();return;}if(share&&!(source instanceof File)){android.widget.Toast.makeText(context,"Đang tải file để chia sẻ…",android.widget.Toast.LENGTH_SHORT).show();File dir=new File(context.getCacheDir(),"shared");if(!dir.exists()&&!dir.mkdirs()){android.widget.Toast.makeText(context,"Không tạo được file chia sẻ.",android.widget.Toast.LENGTH_LONG).show();return;}File target=new File(dir,photo.getId());com.google.firebase.storage.FirebaseStorage.getInstance().getReferenceFromUrl(source.toString()).getFile(target).addOnSuccessListener(snapshot->{if(!context.isDestroyed())send(context,target,photo.getMimeType(),true);}).addOnFailureListener(e->android.widget.Toast.makeText(context,e.getLocalizedMessage(),android.widget.Toast.LENGTH_LONG).show());return;}send(context,source,photo.getMimeType(),share);}
 private static void send(android.app.Activity context,Object source,String mime,boolean share){Uri uri=source instanceof File?FileProvider.getUriForFile(context,context.getPackageName()+".files",(File)source):Uri.parse(source.toString());Intent intent=new Intent(share?Intent.ACTION_SEND:Intent.ACTION_VIEW).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(share){intent.setType(mime);intent.putExtra(Intent.EXTRA_STREAM,uri);intent.setClipData(ClipData.newRawUri("Ảnh",uri));}else intent.setDataAndType(uri,mime);try{context.startActivity(Intent.createChooser(intent,share?"Chia sẻ ảnh":"Phát video"));}catch(ActivityNotFoundException e){android.widget.Toast.makeText(context,"Chưa có ứng dụng hỗ trợ định dạng này.",android.widget.Toast.LENGTH_LONG).show();}}
}

